import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import Webcam from "react-webcam";
import {
  getAuth,
  RecaptchaVerifier,
  signInWithPhoneNumber,
} from "firebase/auth";
import axios from "axios";
import "./AdminLogin.css";
import app from "../../firebase";

const auth = getAuth(app);

const Login = () => {
  const navigate = useNavigate();
  const [name, setName] = useState("");
  const [aadhaarNumber, setAadhaarNumber] = useState("");
  const [phoneNumber, setPhoneNumber] = useState("");
  const [otp, setOtp] = useState("");
  const [otpSent, setOtpSent] = useState(false);
  const [confirmationResult, setConfirmationResult] = useState(null);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [showWebcam, setShowWebcam] = useState(false);
  const [verificationSuccess, setVerificationSuccess] = useState(false);
  const [captureSuccess, setCaptureSuccess] = useState(false);
  const [fingerprintImage, setFingerprintImage] = useState(null);
  const webcamRef = React.useRef(null);

  React.useEffect(() => {
    return () => {
      if (window.recaptchaVerifier) {
        window.recaptchaVerifier.clear();
        delete window.recaptchaVerifier;
      }
    };
  }, []);

  const reCaptchverify = () => {
    if (!window.recaptchaVerifier) {
      window.recaptchaVerifier = new RecaptchaVerifier(
        auth,
        "recaptcha-container",
        {
          size: "normal",
          callback: (response) => {
            console.log("reCAPTCHA solved", response);
          },
          "expired-callback": () => {
            console.log("reCAPTCHA expired");
            window.recaptchaVerifier.render().then((widgetId) => {
              window.recaptchaWidgetId = widgetId;
            });
          },
        }
      );
    }
    return window.recaptchaVerifier;
  };

  const verifyCode = () => {
    if (!confirmationResult) {
      setError("No confirmation result available");
      return Promise.reject("No confirmation result");
    }
    return confirmationResult.confirm(otp);
  };

  const validateInputs = () => {
    if (!name.trim()) {
      setError("Please enter your name as per Aadhaar");
      return false;
    }
    if (!aadhaarNumber || aadhaarNumber.length !== 12) {
      setError("Please enter a valid 12-digit Aadhaar number");
      return false;
    }
    if (!phoneNumber || phoneNumber.length !== 10) {
      setError("Please enter a valid 10-digit phone number");
      return false;
    }
    return true;
  };

  const sendOTP = async () => {
    setError("");
    if (!validateInputs()) return;

    setLoading(true);
    try {
      const verifier = reCaptchverify();
      const formattedPhone = `+91${phoneNumber}`;

      await verifier.render();
      const result = await signInWithPhoneNumber(
        auth,
        formattedPhone,
        verifier
      );

      setConfirmationResult(result);
      setOtpSent(true);
      setError("");
      console.log("OTP sent successfully");
    } catch (error) {
      console.error("OTP sending error:", error);
      setError(`Failed to send OTP: ${error.message}`);
      if (window.recaptchaVerifier) {
        window.recaptchaVerifier.clear();
        delete window.recaptchaVerifier;
      }
    } finally {
      setLoading(false);
    }
  };

  const verifyOTP = async () => {
    setError("");
    if (!otp || otp.length !== 6) {
      setError("Please enter a valid 6-digit OTP");
      return;
    }

    setLoading(true);
    try {
      await verifyCode();
      if (window.recaptchaVerifier) {
        window.recaptchaVerifier.clear();
        delete window.recaptchaVerifier;
      }

      const recaptchaContainer = document.getElementById("recaptcha-container");
      if (recaptchaContainer) {
        recaptchaContainer.innerHTML = "";
      }

      setVerificationSuccess(true);
      setShowWebcam(true);
      setError("");
    } catch (error) {
      setError("Invalid OTP. Please try again.");
      console.error("OTP verification error:", error);
    } finally {
      setLoading(false);
    }
  };

  const captureFaceImage = () => {
    const imageSrc = webcamRef.current.getScreenshot();
    if (!imageSrc) return;

    // Convert base64 to blob
    fetch(imageSrc)
      .then((res) => res.blob())
      .then((blob) => {
        const file = new File([blob], `face_${Date.now()}.png`, {
          type: "image/png",
        });
        submitVerificationData(file);
      });

    setShowWebcam(false);
    setCaptureSuccess(true);
  };

  const handleFingerprintUpload = (e) => {
    const file = e.target.files[0];
    if (file) {
      setFingerprintImage(file);
    }
  };

  const submitVerificationData = async (faceImageFile) => {
    try {
      const formData = new FormData();
      formData.append("name", name);
      formData.append("aadhaarNumber", aadhaarNumber);
      formData.append("phoneNumber", phoneNumber);
      formData.append("otp", otp);
      formData.append("faceImage", faceImageFile);

      if (fingerprintImage) {
        formData.append("fingerprintImage", fingerprintImage);
      }

      const response = await axios.post(
        "http://localhost:5000/api/verify-user",
        formData
      );

      if (response.data.success) {
        setCaptureSuccess(true);
        setTimeout(() => {
          // Reset form
          setName("");
          setAadhaarNumber("");
          setPhoneNumber("");
          setOtp("");
          setOtpSent(false);
          setVerificationSuccess(false);
          setCaptureSuccess(false);
          setFingerprintImage(null);

          alert("Verification completed successfully! Data saved to database.");
        }, 2000);
      }
    } catch (error) {
      setError(
        "Failed to submit verification data: " +
          (error.response?.data?.message || error.message)
      );
    }
  };

  const handleAadhaarChange = (e) => {
    setAadhaarNumber(e.target.value.replace(/\D/g, "").slice(0, 12));
  };

  const handlePhoneChange = (e) => {
    setPhoneNumber(e.target.value.replace(/\D/g, "").slice(0, 10));
  };

  const handleOtpChange = (e) => {
    setOtp(e.target.value.replace(/\D/g, "").slice(0, 6));
  };

  const goToAdminLogin = () => {
    navigate("/admin-login");
  };

  return (
    <div className="login-background">
      <div className="login-container">
        <div className="user-login">
          <h2>🗳️ E-Voting User Verification</h2>
          <div id="recaptcha-container"></div>

          {error && <div className="error-message">{error}</div>}

          {verificationSuccess && !showWebcam && !captureSuccess && (
            <div className="success-message">
              OTP Verified! Please complete biometric verification.
            </div>
          )}

          {captureSuccess && (
            <div className="success-message">
              ✅ Verification Complete! Data saved to database.
            </div>
          )}

          {!verificationSuccess ? (
            <>
              <input
                type="text"
                placeholder="Full Name as per Aadhaar"
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="form-input"
              />

              <input
                type="text"
                placeholder="Aadhaar Number (12 digits)"
                value={aadhaarNumber}
                onChange={handleAadhaarChange}
                className="form-input"
                maxLength="12"
              />

              <input
                type="text"
                placeholder="Phone Number (10 digits)"
                value={phoneNumber}
                onChange={handlePhoneChange}
                className="form-input"
                maxLength="10"
              />

              {!otpSent ? (
                <button
                  onClick={sendOTP}
                  className="otp-button"
                  disabled={loading}
                >
                  {loading ? "Sending OTP..." : "📱 Send OTP"}
                </button>
              ) : (
                <>
                  <input
                    type="text"
                    placeholder="Enter OTP (6 digits)"
                    value={otp}
                    onChange={handleOtpChange}
                    className="form-input"
                    maxLength="6"
                  />
                  <div className="button-group">
                    <button
                      onClick={verifyOTP}
                      className="verify-button"
                      disabled={loading}
                    >
                      {loading ? "Verifying..." : "✅ Verify OTP"}
                    </button>
                    <button
                      onClick={sendOTP}
                      className="resend-button"
                      disabled={loading}
                    >
                      🔄 Resend OTP
                    </button>
                  </div>
                </>
              )}
            </>
          ) : null}

          {showWebcam && (
            <div className="webcam-section">
              <h3>📷 Face Verification</h3>
              <Webcam
                audio={false}
                ref={webcamRef}
                screenshotFormat="image/png"
                width={320}
                height={240}
                style={{ borderRadius: "8px", border: "2px solid #ddd" }}
              />
              <br />
              <div className="button-group">
                <button onClick={captureFaceImage} className="capture-button">
                  📸 Capture & Verify
                </button>
                <button
                  onClick={() => setShowWebcam(false)}
                  className="resend-button"
                >
                  ❌ Cancel
                </button>
              </div>

              <div
                className="fingerprint-section"
                style={{ marginTop: "20px" }}
              >
                <h4>👆 Fingerprint Upload (Optional)</h4>
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleFingerprintUpload}
                  className="form-input"
                />
              </div>
            </div>
          )}

          <div style={{ marginTop: "20px", textAlign: "center" }}>
            <button onClick={goToAdminLogin} className="admin-btn">
              👨‍💼 Admin Login
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;
